SELECT COUNT(*) FROM votes as v, comments as c, posts as p, postLinks as pl, users as u WHERE u.Id = c.UserId AND p.Id = pl.PostId AND p.Id = c.PostId AND u.Id = v.UserId AND v.BountyAmount<=50 AND v.CreationDate>=CAST('2010-07-21 00:00:00' AS TIMESTAMP) AND v.CreationDate<=CAST('2014-09-14 00:00:00' AS TIMESTAMP) AND c.CreationDate>=CAST('2010-07-26 20:21:15' AS TIMESTAMP) AND c.CreationDate<=CAST('2014-09-13 01:26:16' AS TIMESTAMP) AND p.Score>=-1 AND p.Score<=19 AND p.CommentCount<=13
